namespace TCPMS.Api.Infrastructure;

/// <summary>
/// 中国大陆省、市、区县三级行政区种子数据。
/// 数据不包含街道、乡镇及港澳台，便于门店三级地区选择器使用。
/// 节点与后台前端 china-area-data@5.0.1 保持一致；包内下级节点统一归入 District。
/// </summary>
public static class RegionSeedData
{
    public sealed record SeedRegion(string Code, string? ParentCode, string Level, string Name, string FullName, int SortOrder, string? Initial);

    public static IEnumerable<SeedRegion> GetRegions()
    {
        foreach (var line in Data.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var fields = line.Split('|', 7);
            // The upstream dictionary also carries 9-digit street/town
            // records for a few cities. Region management stops at the
            // province/city/district level, so only standard 6-digit
            // administrative codes are seeded.
            if (fields.Length == 7 &&
                fields[0].Length == 6 &&
                int.TryParse(fields[5], out var sortOrder))
            {
                yield return new SeedRegion(fields[0], string.IsNullOrWhiteSpace(fields[1]) ? null : fields[1], fields[2], fields[3], fields[4], sortOrder, string.IsNullOrWhiteSpace(fields[6]) ? null : fields[6]);
            }
        }
    }

    private const string Data = """
